const state={filter:'all',lineage:'all'};
const search=document.querySelector('#search'),era=document.querySelector('#era'),sort=document.querySelector('#sort'),lineage=document.querySelector('#lineage');
PAPERS.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name+' · '+p.year;lineage.append(o)});
function releaseCard(x){return `<article id="${x.id}" class="card release-card ${x.featured?'featured':''}"><div class="card-top"><span class="release">${x.release}</span><span class="tag">${x.tags.join(' / ')}</span></div><h3>${x.title}</h3><p>${x.text}</p><div class="apis">${x.apis.map(a=>`<code>${a}</code>`).join('')}</div><div class="paper-connections">${x.links.length?x.links.map(l=>`<button class="connection ${l.type}" data-lineage="${l.paper.id}" title="${l.reason}"><span>${l.paper.year} · ${l.paper.name}</span><small>${RELATIONS[l.type]} · 계보 보기 ↗</small></button>`).join(''):'<p class="no-paper">논문 직접 대응 미확인 · 제품·API 변화는 단일 논문과 일치하지 않을 수 있습니다.</p>'}</div><details><summary>학습 질문 · 근거 상세</summary><p>${x.question}</p>${x.note?`<p>${x.note}</p>`:''}${x.links.map(l=>`<p><b>${l.paper.name}</b> · ${l.reason} <a href="${l.paper.evidence}" target="_blank" rel="noopener">대응 근거 ↗</a></p>`).join('')}</details><div class="card-foot"><span class="evidence ${x.verified?'':'draft'}">${x.verified?'● 릴리즈 근거 확인':'◐ 릴리즈 추가 확인'}</span><a href="${x.url}" target="_blank" rel="noopener">공식 문서 ↗</a></div></article>`;}
function paperCard(p){return `<article id="paper-${p.id}" class="paper-card"><div class="paper-kicker">RESEARCH · ${p.venue}</div><h3>${p.name}</h3><p class="paper-title">${p.title}</p><p class="authors">${p.authors}</p><p>${p.text}</p>${p.note?`<p class="paper-note">${p.note}</p>`:''}<div class="paper-destinations">${p.edges.map(e=>`<span>${e[0]} <small>${RELATIONS[e[2]]}</small></span>`).join('')}</div><div class="paper-actions"><a href="${p.url}" target="_blank" rel="noopener">논문 / 원문 ↗</a><a href="${p.evidence}" target="_blank" rel="noopener">API 근거 ↗</a><button data-lineage="${p.id}">연결된 릴리즈 보기 →</button></div></article>`;}
function render(){const query=search.value.trim().toLowerCase();const matches=p=>[p.name,p.title,p.authors,p.text].join(' ').toLowerCase().includes(query);const matchedPapers=new Set(PAPERS.filter(matches).map(p=>p.id));
const rows=HISTORY.filter(x=>(state.filter==='all'||x.tags.includes(state.filter))&&(era.value==='all'||x.era===era.value)&&(state.lineage==='all'||x.links.some(l=>l.paper.id===state.lineage))&&(!query||[x.release,x.title,x.text,x.apis.join(' '),x.question].join(' ').toLowerCase().includes(query)||x.links.some(l=>matchedPapers.has(l.paper.id))));
const papers=PAPERS.filter(p=>(state.lineage==='all'||p.id===state.lineage)&&(rows.some(r=>r.links.some(l=>l.paper.id===p.id))||(era.value==='all'&&(state.filter==='all'||p.tags.includes(state.filter))&&matches(p))));
const years=[...new Set([...rows.map(r=>Number(r.release.slice(1,5))),...papers.map(p=>p.year)])].sort((a,b)=>(a-b)*(sort.value==='asc'?1:-1));
document.querySelector('#count').textContent=`논문·기술보고서 ${papers.length}편 · MATLAB 변경 ${rows.length}개`;
document.querySelector('#cards').innerHTML=years.length?years.map((year,index)=>{const rs=rows.filter(r=>Number(r.release.slice(1,5))===year).sort((a,b)=>a.release.localeCompare(b.release)*(sort.value==='asc'?1:-1));const ps=papers.filter(p=>p.year===year);const gap=index?Math.abs(year-years[index-1]):0;return `${gap>1?`<div class="year-gap">${gap}년 간격 · 사건이 있는 연도만 표시</div>`:''}<div class="year-row" id="year-${year}"><div class="paper-lane">${ps.map(paperCard).join('')}${!ps.length?'<div class="lane-empty">이 해의 선정 논문 없음</div>':''}</div><div class="year-marker"><span>${year}</span><i></i></div><div class="release-lane">${rs.map(releaseCard).join('')}${!rs.length?'<div class="lane-empty">MATLAB 연결은 이후 릴리즈에서 이어집니다</div>':''}</div></div>`}).join(''):'<div class="empty"><h3>일치하는 항목이 없습니다.</h3><p>검색어를 줄이거나 필터를 초기화해 보세요.</p></div>';
document.querySelector('#year-jumps').innerHTML=years.map(y=>`<a href="#year-${y}">${y}</a>`).join('');
const p=PAPERS.find(p=>p.id===state.lineage);document.querySelector('#lineage-summary').hidden=!p;
if(p){document.querySelector('#lineage-summary').innerHTML=`<div><span class="eyebrow">SELECTED RESEARCH LINEAGE</span><h3>${p.name}의 연구 → 제품 계보</h3><p>${p.year} ${p.venue} <span>→</span> ${p.edges.map(e=>e[0]).filter((v,i,a)=>a.indexOf(v)===i).join(' → ')}</p><small>연도 차이는 출판 연도와 릴리즈 연도의 차이이며, 개발에 걸린 기간이 아닙니다.</small></div><button id="clear-lineage">전체 연표로 돌아가기 ×</button>`;document.querySelector('#clear-lineage').addEventListener('click',reset);}
document.querySelectorAll('[data-lineage]').forEach(b=>b.onclick=()=>selectLineage(b.dataset.lineage));
}
function selectLineage(id){state.lineage=id;lineage.value=id;search.value='';era.value='all';state.filter='all';updateButtons();render();document.querySelector('#timeline').scrollIntoView({behavior:'smooth'});}
function updateButtons(){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter)));}
function reset(){search.value='';era.value='all';sort.value='asc';state.filter='all';state.lineage='all';lineage.value='all';updateButtons();render();}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;updateButtons();render()}));
search.addEventListener('input',render);era.addEventListener('change',render);sort.addEventListener('change',render);lineage.addEventListener('change',()=>selectLineage(lineage.value));document.querySelector('#reset').addEventListener('click',reset);
document.querySelectorAll('[data-era]').forEach(a=>a.addEventListener('click',()=>{reset();era.value=a.dataset.era;render()}));render();
